mapper.sql:
SELECT t.*, t.is_blocked AS blocked
FROM task t
WHERE t.workspace_id = #{workspaceId} AND t.req_id = #{reqId}

mapper.select:
SELECT rp.id AS id, rp.workspace_id AS workspaceId, rp.version_id AS versionId, pv.name AS versionName, pv.status AS versionStatus, pv.target_date AS versionTargetDate, pv.req_id AS reqId, r.name AS projectName, (SELECT GROUP_CONCAT(v2.name ORDER BY r2.name, v2.name, v2.id SEPARATOR ' / ') FROM version_release_plan_version x2 INNER JOIN project_version v2 ON v2.workspace_id = x2.workspace_id AND v2.id = x2.version_id INNER JOIN requirement r2 ON r2.workspace_id = v2.workspace_id AND r2.id = v2.req_id WHERE x2.workspace_id = rp.workspace_id AND x2.plan_id = rp.id) AS versionNames, (SELECT GROUP_CONCAT(DISTINCT r2.name ORDER BY r2.name SEPARATOR ' / ') FROM version_release_plan_version x2 INNER JOIN project_version v2 ON v2.workspace_id = x2.workspace_id AND v2.id = x2.version_id INNER JOIN requirement r2 ON r2.workspace_id = v2.workspace_id AND r2.id = v2.req_id WHERE x2.workspace_id = rp.workspace_id AND x2.plan_id = rp.id) AS projectNames, (SELECT COUNT(*) FROM version_release_plan_version x2 WHERE x2.workspace_id = rp.workspace_id AND x2.plan_id = rp.id) AS versionCount, rp.planned_at AS plannedAt, rp.owner_user_id AS ownerUserId, u.display_name AS ownerName, rp.environment AS environment, rp.coverage AS coverage, rp.status AS status, rp.revision AS revision, rp.notes AS notes, rp.risks AS risks, (SELECT COUNT(*) FROM version_release_plan_task pt WHERE pt.workspace_id = rp.workspace_id AND pt.plan_id = rp.id) AS plannedTaskCount FROM version_release_plan rp INNER JOIN project_version pv ON pv.workspace_id = rp.workspace_id AND pv.id = rp.version_id INNER JOIN requirement r ON r.workspace_id = pv.workspace_id AND r.id = pv.req_id LEFT JOIN app_user u ON u.id = rp.owner_user_id WHERE rp.workspace_id = #{workspaceId} AND EXISTS ( SELECT 1 FROM version_release_plan_version x INNER JOIN project_version v ON v.workspace_id = x.workspace_id AND v.id = x.version_id INNER JOIN requirement pr ON pr.workspace_id = v.workspace_id AND pr.id = v.req_id WHERE x.workspace_id = rp.workspace_id AND x.plan_id = rp.id AND pr.archived_at IS NULL AND v.req_id = #{reqId}
AND NOT EXISTS (SELECT 1 FROM project_member pm WHERE pm.workspace_id = x.workspace_id AND pm.project_id = v.req_id AND pm.user_id = #{viewerId} AND pm.access = 'none')
) AND rp.planned_at >= #{from} AND rp.planned_at < DATE_ADD(#{to}, INTERVAL 1 DAY) AND rp.environment = #{environment}
AND rp.status IN #{status}
ORDER BY (rp.planned_at IS NULL), rp.planned_at, rp.id LIMIT #{limit}

SELECT * FROM version_release WHERE workspace_id = #{workspaceId} AND version_id = #{versionId}
  AND result = 'success' AND environment = 'production' AND operation IN ('deploy','redeploy')
ORDER BY occurred_at DESC, recorded_at DESC, id DESC LIMIT 1
